import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import "./AdminDashboard.css";

const AdminDashboard = () => {
  const navigate = useNavigate();
  const [users, setUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [electionResults, setElectionResults] = useState(null);
  const [votingStats, setVotingStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [exportLoading, setExportLoading] = useState(false);
  const [activeTab, setActiveTab] = useState("users");
  const [showAddCandidate, setShowAddCandidate] = useState(false);
  const [newCandidate, setNewCandidate] = useState({
    name: "",
    party: "",
    symbol: "",
  });

  useEffect(() => {
    const token = localStorage.getItem("adminToken");
    if (!token) {
      navigate("/admin-login");
      return;
    }
    fetchUsers();
    fetchCandidates();
    fetchVotingStats();
  }, [navigate]);

  const fetchUsers = async () => {
    try {
      const token = localStorage.getItem("adminToken");
      const response = await axios.get("http://localhost:5000/api/users", {
        headers: { Authorization: token },
      });
      setUsers(response.data);
      setLoading(false);
    } catch (error) {
      console.error("Error fetching users:", error);
      if (error.response?.status === 401) {
        localStorage.removeItem("adminToken");
        navigate("/admin-login");
      }
      setLoading(false);
    }
  };

  const fetchCandidates = async () => {
    try {
      const response = await axios.get("http://localhost:5000/api/candidates");
      setCandidates(response.data);
    } catch (error) {
      console.error("Error fetching candidates:", error);
    }
  };

  const fetchElectionResults = async () => {
    try {
      const token = localStorage.getItem("adminToken");
      const response = await axios.get(
        "http://localhost:5000/api/election-results",
        {
          headers: { Authorization: token },
        }
      );
      setElectionResults(response.data);
    } catch (error) {
      console.error("Error fetching election results:", error);
    }
  };

  const fetchVotingStats = async () => {
    try {
      const token = localStorage.getItem("adminToken");
      const response = await axios.get(
        "http://localhost:5000/api/voting-stats",
        {
          headers: { Authorization: token },
        }
      );
      setVotingStats(response.data.stats);
    } catch (error) {
      console.error("Error fetching voting stats:", error);
    }
  };

  const exportToExcel = async () => {
    try {
      setExportLoading(true);
      const token = localStorage.getItem("adminToken");
      const response = await axios.get(
        "http://localhost:5000/api/export-excel",
        {
          headers: { Authorization: token },
          responseType: "blob",
        }
      );

      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement("a");
      link.href = url;
      link.setAttribute(
        "download",
        `UserVerifications_${new Date().getTime()}.xlsx`
      );
      document.body.appendChild(link);
      link.click();
      link.remove();

      alert("✅ Excel file downloaded successfully!");
    } catch (error) {
      console.error("Error exporting Excel:", error);
      alert(
        "❌ Error exporting Excel file: " +
          (error.response?.data?.message || error.message)
      );
    } finally {
      setExportLoading(false);
    }
  };

  const handleAddCandidate = async (e) => {
    e.preventDefault();
    try {
      const token = localStorage.getItem("adminToken");
      const response = await axios.post(
        "http://localhost:5000/api/candidates",
        newCandidate,
        {
          headers: { Authorization: token },
        }
      );

      if (response.data.success) {
        alert("✅ Candidate added successfully!");
        setNewCandidate({ name: "", party: "", symbol: "" });
        setShowAddCandidate(false);
        fetchCandidates();
      }
    } catch (error) {
      console.error("Error adding candidate:", error);
      alert(
        "❌ Failed to add candidate: " +
          (error.response?.data?.message || error.message)
      );
    }
  };

  const handleLogout = () => {
    localStorage.removeItem("adminToken");
    navigate("/admin-login");
  };

  const goToUserLogin = () => {
    navigate("/login");
  };

  const viewFaceImage = (faceImage) => {
    if (faceImage) {
      const imageUrl = `http://localhost:5000/uploads/${faceImage}`;
      window.open(imageUrl, "_blank");
    }
  };

  if (loading) return <div className="loading">Loading user data...</div>;

  return (
    <div className="admin-dashboard">
      <div className="dashboard-header">
        <div>
          <h1>👨‍💼 E-Voting Admin Dashboard</h1>
          <p>Manage and monitor user verifications and elections</p>
        </div>
        <div className="header-actions">
          <button onClick={goToUserLogin} className="user-login-btn">
            👤 User Login
          </button>
          <button onClick={handleLogout} className="logout-btn">
            🚪 Logout
          </button>
        </div>
      </div>

      {/* Navigation Tabs */}
      <div className="admin-tabs">
        <button
          className={activeTab === "users" ? "tab-active" : "tab"}
          onClick={() => setActiveTab("users")}
        >
          👥 Users
        </button>
        <button
          className={activeTab === "candidates" ? "tab-active" : "tab"}
          onClick={() => setActiveTab("candidates")}
        >
          🏆 Candidates
        </button>
        <button
          className={activeTab === "results" ? "tab-active" : "tab"}
          onClick={() => {
            setActiveTab("results");
            fetchElectionResults();
          }}
        >
          📊 Results
        </button>
      </div>

      {/* Dashboard Stats */}
      <div className="dashboard-stats">
        <div className="stat-card total-users">
          <h3>Total Registered Users</h3>
          <p>{users.length}</p>
        </div>
        <div className="stat-card today-users">
          <h3>Total Candidates</h3>
          <p>{candidates.length}</p>
        </div>
        <div className="stat-card unique-voters">
          <h3>Voting Percentage</h3>
          <p>{votingStats ? `${votingStats.votingPercentage}%` : "0%"}</p>
        </div>
        <div className="stat-card total-votes">
          <h3>Total Votes Cast</h3>
          <p>{votingStats ? votingStats.total_voted : 0}</p>
        </div>
      </div>

      {/* Users Tab */}
      {activeTab === "users" && (
        <>
          <div className="dashboard-actions">
            <button
              onClick={exportToExcel}
              className="export-btn"
              disabled={users.length === 0 || exportLoading}
            >
              {exportLoading
                ? "📊 Exporting..."
                : `📊 Export to Excel (${users.length} records)`}
            </button>
            <button onClick={fetchUsers} className="refresh-btn">
              🔄 Refresh Data
            </button>
          </div>

          {users.length === 0 ? (
            <div className="no-data">
              <h3>📭 No user verification data found</h3>
              <p>
                Users will appear here after they complete verification through
                the user login page.
              </p>
            </div>
          ) : (
            <div className="users-table-container">
              <table className="users-table">
                <thead>
                  <tr>
                    <th>ID</th>
                    <th>Name</th>
                    <th>Aadhar Number</th>
                    <th>Phone Number</th>
                    <th>OTP</th>
                    <th>Face Image</th>
                    <th>Voter ID</th>
                    <th>Email</th>
                    <th>Email OTP</th>
                    <th>IP Address</th>
                    <th>Timestamp</th>
                  </tr>
                </thead>
                <tbody>
                  {users.map((user) => (
                    <tr key={user.ID || user.id}>
                      <td>{user.ID || user.id}</td>
                      <td>{user.name}</td>
                      <td>{user.aadhar_number || user.aadhaar_number}</td>
                      <td>{user.phone_number}</td>
                      <td>{user.otp}</td>
                      <td>
                        {user.face_image ? (
                          <button
                            className="view-image-btn"
                            onClick={() => viewFaceImage(user.face_image)}
                            title="Click to view face image"
                          >
                            📷 View
                          </button>
                        ) : (
                          "❌"
                        )}
                      </td>
                      <td>{user.voterid || user.voter_id}</td>
                      <td>{user.email}</td>
                      <td>{user.email_otp}</td>
                      <td>{user.ip_address}</td>
                      <td>{new Date(user.timestamp).toLocaleString()}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </>
      )}

      {/* Candidates Tab */}
      {activeTab === "candidates" && (
        <div className="candidates-management">
          <div className="section-header">
            <h2>🏆 Candidate Management</h2>
            <button
              onClick={() => setShowAddCandidate(!showAddCandidate)}
              className="add-candidate-btn"
            >
              {showAddCandidate ? "❌ Cancel" : "➕ Add Candidate"}
            </button>
          </div>

          {showAddCandidate && (
            <div className="add-candidate-form">
              <h3>Add New Candidate</h3>
              <form onSubmit={handleAddCandidate}>
                <div className="form-group">
                  <input
                    type="text"
                    placeholder="Candidate Name"
                    value={newCandidate.name}
                    onChange={(e) =>
                      setNewCandidate({ ...newCandidate, name: e.target.value })
                    }
                    className="form-input"
                    required
                  />
                </div>
                <div className="form-group">
                  <input
                    type="text"
                    placeholder="Party Name"
                    value={newCandidate.party}
                    onChange={(e) =>
                      setNewCandidate({
                        ...newCandidate,
                        party: e.target.value,
                      })
                    }
                    className="form-input"
                    required
                  />
                </div>
                <div className="form-group">
                  <input
                    type="text"
                    placeholder="Party Symbol (Optional)"
                    value={newCandidate.symbol}
                    onChange={(e) =>
                      setNewCandidate({
                        ...newCandidate,
                        symbol: e.target.value,
                      })
                    }
                    className="form-input"
                  />
                </div>
                <button type="submit" className="submit-candidate-btn">
                  ✅ Add Candidate
                </button>
              </form>
            </div>
          )}

          <div className="candidates-list-admin">
            <h3>Current Candidates ({candidates.length})</h3>
            {candidates.length === 0 ? (
              <div className="no-candidates">
                <p>No candidates added yet.</p>
              </div>
            ) : (
              <div className="candidates-grid-admin">
                {candidates.map((candidate) => (
                  <div key={candidate.id} className="candidate-card-admin">
                    <div className="candidate-info-admin">
                      <h4>{candidate.name}</h4>
                      <p className="party-admin">{candidate.party}</p>
                      {candidate.symbol && (
                        <p className="symbol-admin">{candidate.symbol}</p>
                      )}
                      <p className="votes-admin">
                        Votes: <strong>{candidate.votes || 0}</strong>
                      </p>
                      <p className="created-date">
                        Added:{" "}
                        {new Date(candidate.created_at).toLocaleDateString()}
                      </p>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      )}

      {/* Results Tab */}
      {activeTab === "results" && (
        <div className="election-results">
          <div className="section-header">
            <h2>📊 Election Results</h2>
            <button onClick={fetchElectionResults} className="refresh-btn">
              🔄 Refresh Results
            </button>
          </div>

          {electionResults ? (
            <div className="results-container">
              {/* Winner Announcement */}
              {electionResults.winner && (
                <div className="winner-announcement">
                  <div className="winner-badge">🏆 WINNER</div>
                  <h3>{electionResults.winner.name}</h3>
                  <p className="winner-party">{electionResults.winner.party}</p>
                  <p className="winner-votes">
                    {electionResults.winner.votes} Votes
                  </p>
                </div>
              )}

              {electionResults.isTie && (
                <div className="tie-announcement">
                  <h3>🤝 Election Tie</h3>
                  <p>Multiple candidates have the same number of votes.</p>
                </div>
              )}

              {/* Results Summary */}
              <div className="results-summary">
                <div className="summary-card">
                  <h4>Total Votes Cast</h4>
                  <p className="summary-number">{electionResults.totalVotes}</p>
                </div>
                <div className="summary-card">
                  <h4>Total Candidates</h4>
                  <p className="summary-number">
                    {electionResults.candidates.length}
                  </p>
                </div>
              </div>

              {/* Detailed Results */}
              <div className="detailed-results">
                <h4>Detailed Results</h4>
                <table className="results-table">
                  <thead>
                    <tr>
                      <th>Rank</th>
                      <th>Candidate</th>
                      <th>Party</th>
                      <th>Votes</th>
                      <th>Percentage</th>
                    </tr>
                  </thead>
                  <tbody>
                    {electionResults.candidates.map((candidate, index) => (
                      <tr
                        key={candidate.id}
                        className={index === 0 ? "first-place" : ""}
                      >
                        <td>#{index + 1}</td>
                        <td>
                          <strong>{candidate.name}</strong>
                          {candidate.symbol && (
                            <span className="candidate-symbol">
                              {" "}
                              ({candidate.symbol})
                            </span>
                          )}
                        </td>
                        <td>{candidate.party}</td>
                        <td className="vote-count">
                          {candidate.total_votes || 0}
                        </td>
                        <td className="vote-percentage">
                          {electionResults.totalVotes > 0
                            ? `${(
                                (candidate.total_votes /
                                  electionResults.totalVotes) *
                                100
                              ).toFixed(1)}%`
                            : "0%"}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          ) : (
            <div className="no-results">
              <p>Click "Refresh Results" to see election results.</p>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;
